it.each(['completed', 'cancelled', 'failed'] as const)(
    'never executes residual child work after %s',
    (status) => {
      const run = childRun('running');
      run.status = status;
      const view = projectWorkflowApplicationRun(application, run);
      expect(view.continuation.mode).toBe(status === 'failed' ? 'reconcile' : 'done');
      expect(view.continuation.nextRequest).toBeUndefined();
    },
  )

it('publishes pending stop confirmation instead of a done continuation after logical cancellation', () => {
  const run = childRun('running');
  run.children = [];
  run.status = 'cancelled';
  const action = run.actions[0];
  action.type = 'invoke_skill';
  action.status = 'cancelled';
  action.claim = { executorId: 'host', token: 'original-token' };
  const view = projectWorkflowApplicationRun(application, run);
  expect(view.continuation.mode).toBe('reconcile');
  expect(view.current.actions).toHaveLength(1);
  expect(view.current.actions[0]).toMatchObject({
    stopConfirmationRequired: true,
    confirmStoppedRequest: {
      operation: 'cancel',
      stoppedActions: [
        {
          actionId: action.id,
          claimToken: 'original-token',
          attempt: action.attempt,
          inputHash: action.inputHash,
        },
      ],
    },
  });
  action.cancellation = {
    actionId: action.id,
    claimToken: 'original-token',
    attempt: action.attempt,
    inputHash: action.inputHash,
    evidence: 'stopped',
  };
  const stopped = projectWorkflowApplicationRun(application, run);
  expect(stopped.continuation.mode).toBe('done');
  expect(stopped.current.actions).toHaveLength(0);
})

it.each(['cancel', 'acknowledgeStopped'] as const)(
  'retains cancelled claims across cold reloads until the original executor confirms stopping through %s',
  async (operation) => {
    const f = await fixture();
    const action = f.run.actions.find((item) => item.stepId === 'left')!;
    await f.runtime.claim({
      runId: f.run.runId,
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'local-skill',
      capabilities: ['skill-script'],
      claimToken: 'original-writer',
    });

    const restored = structuredClone(await f.runtime.inspect(f.run.runId));
    restored.runId = 'restored-cancelled';
    restored.revision = 50;
    restored.status = 'cancelled';
    restored.actions = restored.actions.map((item) => ({
      ...item,
      runId: restored.runId,
      status: ['pending', 'running'].includes(item.status) ? 'cancelled' : item.status,
    }));
    await expect(
      f.loaded.store.restoreCheckpoint!(restored.runId, null, restored),
    ).rejects.toMatchObject({ code: 'SCOPE_HELD' });
    let cancelled = await f.runtime.cancel({
      runId: f.run.runId,
      reason: 'user cancellation',
    });
    const store = createFileRuntimeStore({
      rootDir: path.join(
        resolveWorkspaceRuntimeRootSync(f.root),
        'applications',
        f.loaded.identity.id,
      ),
      mirroredRevisionPaths: ['run.revision'],
    });
    expect(await store.readPartitionMetadata(cancelled.runId)).toBe('active');
    const loaded = await loadWorkflowApplication({
      file: f.disk.file,
      projectRoot: f.root,
    });
    const runtime = createRuntime({
      ...loaded.implementation,
      store: loaded.store,
    });
    let peer = await runtime.start({
      runId: 'peer',
      workflow: { id: 'editorial', version: '1' },
      input: f.run.input,
    });
    peer = await runtime.execute({
      runId: peer.runId,
      actionId: peer.actions[0].id,
      executorId: 'tool-host',
    });
    peer = await runtime.resolveWait({
      runId: peer.runId,
      waitId: peer.waits[0].id,
      proposalHash: peer.waits[0].proposalHash,
      decisionId: 'peer-approval',
      choice: 'approved',
    });
    peer = await runtime.execute({
      runId: peer.runId,
      actionId: peer.actions.at(-1)!.id,
      executorId: 'tool-host',
    });
    const next = peer.actions.find((item) => item.stepId === 'left')!;
    const claim = {
      runId: peer.runId,
      actionId: next.id,
      attempt: next.attempt,
      inputHash: next.inputHash,
      executorId: 'local-skill',
      capabilities: ['skill-script'],
      claimToken: 'peer-writer',
    };
    await expect(runtime.claim(claim)).rejects.toMatchObject({
      code: 'SCOPE_HELD',
    });
    const acknowledge = (
      stoppedActions: Parameters<typeof runtime.acknowledgeStopped>[0]['stoppedActions'],
    ) =>
      operation === 'cancel'
        ? runtime.cancel({
            runId: cancelled.runId,
            reason: 'confirm',
            stoppedActions,
          })
        : runtime.acknowledgeStopped({
            runId: cancelled.runId,
            stoppedActions,
          });
    const stopped = {
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      claimToken: 'wrong',
      evidence: 'The original process and its children have exited.',
    };
    await expect(acknowledge([stopped])).rejects.toMatchObject({
      code: 'STALE_ACTION',
    });
    await expect(runtime.claim(claim)).rejects.toMatchObject({
      code: 'SCOPE_HELD',
    });
    cancelled = await acknowledge([{ ...stopped, claimToken: 'original-writer' }]);
    if (operation === 'acknowledgeStopped') {
      expect(
        cancelled.actions.find((item) => item.id === action.id)?.executionStop?.claimToken,
      ).toBe('original-writer');
      expect(cancelled.actions.find((item) => item.id === action.id)?.cancellation).toBeUndefined();
    }
    expect(await store.readPartitionMetadata(cancelled.runId)).toBe('closed');
    expect((await runtime.claim(claim)).actions.find((item) => item.id === next.id)?.status).toBe(
      'running',
    );
    // 原取消的重复提交保持兼容，封存不永久阻止幂等确认。
    await acknowledge([{ ...stopped, claimToken: 'original-writer' }]);
    expect(await store.readPartitionMetadata(cancelled.runId)).toBe('closed');
  },
)

it('fences raw writers after application holder coordination is enabled', async () => {
  const f = await fixture();
  const store = createFileRuntimeStore({
    rootDir: path.join(
      resolveWorkspaceRuntimeRootSync(f.root),
      'applications',
      f.loaded.identity.id,
    ),
    mirroredRevisionPaths: ['run.revision'],
  });
  const old = await f.runtime.start({
    runId: 'ended',
    workflow: { id: 'editorial', version: '1' },
    input: f.run.input,
  });
  const ended = await f.runtime.cancel({
    runId: old.runId,
    reason: 'never executed',
  });
  await expect(store.reopenRun(ended.runId, ended.revision)).rejects.toMatchObject({
    code: 'STORE_WRITER_FENCED',
  });
  expect(await store.readPartitionMetadata(ended.runId)).toBe('closed');
})

it('retains cancelled ownership across cold application reload until exact stop acknowledgement', async () => {
  const project = await root();
  const alpha = await fixture(project, 'alpha');
  const beta = await fixture(project, 'beta');
  const claimed = await alpha.runtime.claim({ ...alpha.request, claimToken: 'original' });
  const action = claimed.actions.at(-1)!;
  await alpha.runtime.cancel({ runId: claimed.runId, reason: 'cancel scheduling only' });
  const reload = await loadWorkflowApplication({ file: beta.disk.file, projectRoot: project });
  const runtime = createRuntime({ ...reload.implementation, store: reload.store });
  await expect(runtime.claim(beta.request)).rejects.toMatchObject({ code: 'SCOPE_HELD' });
  await alpha.runtime.acknowledgeStopped({
    runId: claimed.runId,
    stoppedActions: [
      {
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        claimToken: 'original',
        evidence: 'The original executor and all child processes have exited.',
      },
    ],
  });
  expect((await runtime.claim(beta.request)).actions.at(-1)?.status).toBe('running');
})

it('does not read inactive peer Run checkpoints or their full member inventory on a warm claim', async () => {
  const project = await root();
  const alpha = await fixture(project, 'alpha');
  await alpha.runtime.cancel({ runId: alpha.run.runId, reason: 'no execution' });
  const beta = await fixture(project, 'beta');
  const opened = vi.spyOn(fs, 'open');
  await beta.runtime.claim(beta.request);
  const peerPaths = opened.mock.calls
    .map((call) => String(call[0]))
    .filter((file) => file.includes(`${path.sep}applications${path.sep}alpha${path.sep}`));
  expect(
    peerPaths.some((file) => file.endsWith('checkpoint.json') || file.endsWith('inventory.json')),
  ).toBe(false);
})

it('still permits releasing an existing claim when an unrelated application directory is corrupt', async () => {
  const project = await root();
  const alpha = await fixture(project, 'alpha', 'alpha.txt');
  const beta = await fixture(project, 'beta', 'beta.txt');
  await beta.runtime.claim({ ...beta.request, claimToken: 'beta-owner' });
  await fs.writeFile(
    path.join(resolveWorkspaceRuntimeRootSync(project), 'applications', 'bad-entry'),
    'not a directory',
  );
  const cancelled = await beta.runtime.cancel({
    runId: beta.run.runId,
    reason: 'stop existing execution',
    stoppedActions: [
      {
        actionId: beta.action.id,
        attempt: beta.action.attempt,
        inputHash: beta.action.inputHash,
        claimToken: 'beta-owner',
        evidence: 'The original executor and all child processes have exited.',
      },
    ],
  });
  expect(cancelled.status).toBe('cancelled');
  await expect(alpha.runtime.claim(alpha.request)).rejects.toMatchObject({
    code: 'STORE_INDEX_CORRUPT',
  });
})

it('rejects a pre-claim checkpoint after the writer Store is lost, then restores the original unknown claim and releases only by proof', async () => {
  const project = await root();
  const alpha = await fixture(project, 'alpha');
  const beta = await fixture(project, 'beta');
  const stale = portable(alpha.run);
  const claimed = await alpha.runtime.claim({ ...alpha.request, claimToken: 'actual-writer' });
  const saved = portable(claimed);
  await fs.rm(appDirectory(project), { recursive: true });
  await expect(
    alpha.loaded.store.restoreCheckpoint!(stale.runId, null, stale),
  ).rejects.toMatchObject({ code: 'STORE_INDEX_CORRUPT' });
  expect(await alpha.loaded.store.restoreCheckpoint!(saved.runId, null, saved)).toBe(true);
  await expect(beta.runtime.claim(beta.request)).rejects.toMatchObject({ code: 'SCOPE_HELD' });
  const old = saved.actions.at(-1)!;
  await alpha.runtime.cancel({
    runId: saved.runId,
    reason: 'stop recovered original execution',
    stoppedActions: [
      {
        actionId: old.id,
        attempt: old.attempt,
        inputHash: old.inputHash,
        claimToken: old.claim!.token,
        evidence: 'The original executor and all child processes have exited.',
      },
    ],
  });
  expect((await beta.runtime.claim(beta.request)).actions.at(-1)?.status).toBe('running');
})

it('allows current work after 128 verified completed child Runs without treating history as active width', async () => {
  const f = await childTree(128);
  for (const child of f.run.children) {
    const run = await f.runtime.inspect(child.runId);
    const action = run.actions[0];
    const claimToken = `claim-${run.runId}`;
    await f.runtime.claim({
      runId: run.runId,
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'reader',
      claimToken,
    });
    await f.runtime.recordOutcome({
      runId: run.runId,
      outcome: {
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        claimToken,
        outcomeId: `done-${run.runId}`,
        status: 'succeeded',
        output: null,
      },
    });
  }
  const run = await f.runtime.next({ runId: f.run.runId });
  expect(
    run.actions.filter(
      (action) => action.type === 'child_workflow' && action.status === 'succeeded',
    ),
  ).toHaveLength(128);
  expect(run.actions.at(-1)).toMatchObject({ stepId: 'finish', status: 'pending' });
  expect(await f.hook(run, f.request)).toMatchObject({ allowed: true });
  const invalidOwner = createApplicationHook({
    ...f.hookOptions,
    readChild: async (runId) => ({ ...(await f.runtime.inspect(runId)), lineage: ['other'] }),
  });
  expect(await invalidOwner(run, f.request)).toMatchObject({
    allowed: false,
    reason: '子流程没有当前 SDK Run 的有效归属',
  });
  const disk = await createScopeCycleApplication(root, true);
  const adapted = await loadWorkflowApplication({ file: disk.file, projectRoot: root });
  const writer = adapted.skills.get('writer')!;
  const terminalHook = createApplicationHook({
    ...f.hookOptions,
    manifest: {
      ...f.hookOptions.manifest,
      bindings: [
        {
          workflowId: 'worker',
          stepId: 'work',
          skillId: 'read',
          usage: 'action',
          capability: 'title',
        },
      ],
    },
    skills: new Map([['read', { ...writer, id: 'read' }]]),
  });
  const cancelled = await f.runtime.cancel({ runId: run.runId, reason: 'stop after children' });
  expect(await terminalHook(cancelled, { intent: 'write', targets: ['shared.txt'] })).toMatchObject(
    {
      allowed: false,
      reason: '已结束 Run 的声明产物保持固定；继续修改应启动新的 Run',
    },
  );
  expect(await terminalHook(cancelled, f.request)).toMatchObject({ allowed: true });
})

it('still rejects excessive active child width, including cancelled claims without stop confirmation', async () => {
  const f = await childTree(128);
  expect(await f.hook(f.run, f.request)).toMatchObject({
    allowed: false,
    reason: '活跃子流程超出安全读取范围',
  });
  for (const child of f.run.children) {
    const run = await f.runtime.inspect(child.runId);
    const action = run.actions[0];
    await f.runtime.claim({
      runId: run.runId,
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'reader',
      claimToken: `claim-${run.runId}`,
    });
  }
  const cancelled = await f.runtime.cancel({
    runId: f.run.runId,
    reason: 'user stopped scheduling',
  });
  expect((await f.runtime.inspect(cancelled.children[0].runId)).actions[0]).toMatchObject({
    status: 'cancelled',
    claim: { executorId: 'reader' },
  });
  expect(await f.hook(cancelled, f.request)).toMatchObject({
    allowed: false,
    reason: '活跃子流程超出安全读取范围',
  });
})
